mapper.select:
select a.id, a.title, a.subtitle, a.cover_image as coverImage, a.cover_focus_y as coverFocusY, a.content as content, a.like_count as likeCount, a.author_id as authorId, u.username as authorName, u.image as authorAvatar, a.create_time as publishTime from article a join user u on u.id=a.author_id where a.id in
#{articleId}
and a.is_delete=0

mapper.update:
update article
title = #{title}, subtitle = #{subtitle}, cover_image = #{coverImage}, cover_focus_y = #{coverFocusY}, content = #{content}
where id = #{id} and is_delete = 0

